"""
Execution-grounded verification of agent-authored workspaces.

This module implements the ExecutionHarness which verifies code by actually
running it (parsing, installing, importing, testing) rather than relying on
textual analysis or file counts.
"""

import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import re
import json
import tomllib
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable
from pathlib import Path

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define minimal fallbacks
# to ensure this module is self-contained for the harness logic.
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        filter_bundle,
        partition_bundle,
        count_source_files,
        EXCLUDED_DIR_SEGMENTS,
        EXCLUDED_DIR_SUFFIXES
    )
except ImportError:
    # Fallback definitions if artifacts.py is not yet available in the path
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = Path(path).parts
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path.strip() != path:
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {
            k: v for k, v in bundle.items()
            if not is_generated_path(k) and not is_malformed_path(k)
        }

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        return sum(1 for k in bundle.keys() if any(k.endswith(s) for s in suffixes))


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = sum(1 for g in evaluated if g.passed)
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name:10} : {g.status:7} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional filename
    # Format: ```python\n...``` or ```python filename.py\n...```
    # We look for blocks that might contain a filename hint in the info string
    pattern = r"```(?:python|py)?\s*([^\n`]*)\n(.*?)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for i, (info, content) in enumerate(matches):
        # Try to extract a filename from the info string
        # Common patterns: "path/to/file.py", "file.py", "python file.py"
        filename = None
        info_parts = info.strip().split()
        for part in info_parts:
            if part.endswith('.py'):
                filename = part
                break

        if not filename:
            # If no filename in info, try to guess from content or use index
            # For now, we skip blocks without clear filenames to avoid garbage
            # Or we could use a generic name, but the spec implies path->content
            # If we can't determine a path, we can't really map it.
            # However, sometimes the first line of content is a comment with path.
            # Let's stick to info string extraction. If missing, skip.
            continue

        # Sanitize filename
        filename = filename.strip()
        if not filename:
            continue

        # Ensure it's a valid relative path
        if os.path.isabs(filename):
            # Strip leading slash for relative mapping
            filename = filename.lstrip('/')

        bundle[filename] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter out generated and malformed paths
        authored_bundle = filter_bundle(bundle)

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to disk
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        start_time = time.time()

        # Determine authored files
        if authored is None:
            # Scan directory
            all_files = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                all_files[rel_path] = f.read()
                        except Exception:
                            pass
            authored = all_files

        python_files = {k: v for k, v in authored.items() if k.endswith('.py')}
        authored_count = len(authored)
        python_count = len(python_files)

        gates = []

        # Gate 1: Syntax
        gates.append(self._gate_syntax(python_files))

        # Gate 2: Build
        gates.append(self._gate_build(workdir, authored))

        # Gate 3: Smoke
        gates.append(self._gate_smoke(workdir, python_files))

        # Gate 4: Tests
        gates.append(self._gate_tests(workdir, authored))

        # Gate 5: Telemetry
        gates.append(self._gate_telemetry(python_files))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        report = VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_count,
            python_files=python_count,
            source=source
        )

        return report

    def _gate_syntax(self, python_files: Dict[str, str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        errors = []
        for path, content in python_files.items():
            try:
                ast.parse(content, filename=path)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='; '.join(errors),
                duration_s=duration
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast.parse',
            detail=f"Successfully parsed {len(python_files)} files",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata found (pyproject.toml, setup.py, or setup.cfg)',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='tomllib',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='tomllib',
                    detail=f'Failed to parse pyproject.toml: {e}',
                    duration_s=time.time() - start
                )

        # Attempt pip install
        # Check if pip is available
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pip', '--version'],
                capture_output=True,
                timeout=10
            )
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available',
                duration_s=time.time() - start
            )

        try:
            # Run pip install -e . --no-deps --no-build-isolation
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip_install',
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'pip install error: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, python_files: Dict[str, str]) -> GateResult:
        start = time.time()

        # Identify non-test modules
        # Exclude test files and __init__.py? Spec says "Non-test authored modules"
        # Usually __init__.py is considered a module.
        modules = []
        for path in python_files.keys():
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # src/foo/bar.py -> foo.bar
            # foo/bar.py -> foo.bar
            # We need to handle src/ prefix if present

            # Determine root for import
            # If file is in src/, we add src to PYTHONPATH
            # If file is in root, we add root to PYTHONPATH

            # For simplicity, we'll try to import by relative path from workdir
            # But we need to handle src/ layout

            # Let's collect all potential importable modules
            # We'll try to import them in a subprocess

            # Clean path for module name
            clean_path = path.replace('\\', '/')
            if clean_path.startswith('src/'):
                mod_path = clean_path[4:]
            else:
                mod_path = clean_path

            if mod_path.endswith('.py'):
                mod_name = mod_path[:-3].replace('/', '.')
                if mod_name.endswith('.__init__'):
                    mod_name = mod_name[:-9]
                elif mod_name == '__init__':
                    mod_name = ''

                if mod_name: # Skip root __init__
                    modules.append(mod_name)

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail='No importable non-test modules found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        env = os.environ.copy()
        python_path = [workdir, os.path.join(workdir, 'src')]
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Try to import each module
        failed_modules = []
        skipped_modules = []

        for mod_name in modules:
            try:
                # Run a subprocess to import the module
                code = f"import {mod_name}"
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    # Check for ModuleNotFoundError for third-party packages
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package (not part of the workspace)
                        # This is heuristic. If the module itself is missing, it's a fail.
                        # If a dependency is missing, it's skipped.
                        # We assume if the module name itself is not found, it's a fail.
                        # If a sub-dependency is not found, it's skipped.

                        # Simple check: if the error says "No module named 'mod_name'", it's a fail.
                        # If it says "No module named 'opentelemetry'", it's skipped.

                        # Extract the missing module name
                        match = re.search(r"No module named '([^']+)'", stderr)
                        if match:
                            missing_mod = match.group(1)
                            # If the missing module is the one we are trying to import, it's a fail
                            if missing_mod == mod_name or missing_mod.startswith(mod_name + '.'):
                                failed_modules.append(f"{mod_name}: {stderr}")
                            else:
                                skipped_modules.append(f"{mod_name}: missing dependency {missing_mod}")
                        else:
                            failed_modules.append(f"{mod_name}: {stderr}")
                    else:
                        failed_modules.append(f"{mod_name}: {stderr}")
            except Exception as e:
                failed_modules.append(f"{mod_name}: {e}")

        duration = time.time() - start

        if failed_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail='; '.join(failed_modules),
                duration_s=duration
            )

        if skipped_modules and not failed_modules:
            # If all modules were skipped due to missing deps, return SKIPPED
            # If some passed and some skipped, return PASSED? 
            # Spec: "If module imports fail solely with ModuleNotFoundError... return SKIPPED"
            # This implies if ANY module fails with ModuleNotFoundError, the gate is SKIPPED?
            # Or if ALL modules are skipped?
            # "If no importable modules exist or any module fails with a syntax or runtime error, return FAILED."
            # "If module imports fail solely with ModuleNotFoundError... return SKIPPED"

            # Interpretation: If we have modules, and they all fail with ModuleNotFoundError (deps), then SKIPPED.
            # If some pass and some fail with ModuleNotFoundError, it's ambiguous. 
            # Usually, if we can't verify the code runs because deps are missing, we skip.
            # But if some modules imported fine, we have evidence.
            # Let's say: If any module failed with non-ModuleNotFoundError, FAILED.
            # If all modules either passed or failed with ModuleNotFoundError, and at least one failed with ModuleNotFoundError, SKIPPED.
            # If all passed, PASSED.

            # Actually, if a module imports successfully, it's a pass.
            # If a module fails with ModuleNotFoundError, it's a skip.
            # If we have a mix, we have partial evidence.
            # The spec says "If module imports fail solely with ModuleNotFoundError... return SKIPPED".
            # This suggests if the *reason* for failure is missing deps, we skip.
            # If we have successful imports, we didn't "fail".

            # Let's refine:
            # If any module failed with a real error (syntax/runtime), FAILED.
            # If no modules failed with real errors, but some failed with ModuleNotFoundError, SKIPPED.
            # If all modules imported successfully, PASSED.

            # In our loop, we didn't track successes explicitly, only failures.
            # Let's re-evaluate.

            # We need to know if any module imported successfully.
            # Let's modify the loop to track status.

            # For now, if we have skipped_modules and no failed_modules, it means some might have passed or all skipped.
            # If all skipped, SKIPPED.
            # If some passed, PASSED?

            # Let's assume if we have skipped_modules, we return SKIPPED to be safe, 
            # unless we know for sure some passed.
            # But we don't track passes.

            # Let's change the logic:
            # If failed_modules is empty, and skipped_modules is not empty, return SKIPPED.
            # If failed_modules is empty, and skipped_modules is empty, return PASSED.

            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import',
                detail='Modules skipped due to missing dependencies: ' + '; '.join(skipped_modules),
                duration_s=duration
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import',
            detail=f"Successfully imported {len(modules)} modules",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = []
        for path in authored.keys():
            if path.endswith('.py'):
                # Use full path for basename check to ensure correctness
                full_path = os.path.join(workdir, path)
                basename = os.path.basename(full_path).lower()
                if 'test' in basename:
                    test_files.append(path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='discover',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        env = os.environ.copy()
        python_path = [workdir, os.path.join(workdir, 'src')]
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Check if pytest is installed
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pytest', '--version'],
                capture_output=True,
                timeout=10
            )
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short'] + test_files,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start
                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed',
                        duration_s=duration
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='pytest',
                            detail='Tests skipped due to missing dependencies',
                            duration_s=duration
                        )
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail=f'Tests failed: {result.stderr}',
                        duration_s=duration
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Pytest error: {e}',
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # Run a script that imports each test file and collects/executes tests
            # We'll write a temporary runner script

            runner_code = """
import sys
