    def _gate_telemetry(self, python_files: Dict[str, str]) -> GateResult:
        start = time.time()

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span',
            'start_span',
            'get_tracer',
            'get_tracer_provider',
            'set_tracer_provider',
            'get_meter'
        }

        for path, content in python_files.items():
            try:
                tree = ast.parse(content, filename=path)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls
                if isinstance(node, ast.Call):
                    func = node.func
                    # Direct call: get_tracer()
                    if isinstance(func, ast.Name) and func.id in tracer_methods:
                        has_call = True
                    # Attribute call: tracer.start_span()
                    elif isinstance(func, ast.Attribute) and func.attr in tracer_methods:
                        has_call = True

        duration = time.time() - start

        if not has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No opentelemetry import found',
                duration_s=duration
            )

        if not has_call:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No tracer/span method calls found',
                duration_s=duration
            )

        return GateResult(
            name='telemetry',
            status=PASSED,
            method='ast_analysis',
            detail='OpenTelemetry usage detected',
            duration_s=duration
        )
